SELECT (SELECT count(*) FROM t1) AS t1_rows, (SELECT count(*) FROM t1 WHERE length(x)=8000) AS t1_long_rows, (SELECT count(*) FROM v1) AS v1_rows, (SELECT count(*) FROM t2) AS t2_rows, (SELECT count(*) FROM t2 WHERE b=a*2) AS t2_matching_rows, (SELECT count(DISTINCT a) FROM t2) AS t2_distinct_a, (SELECT min(a) FROM t2) AS min_a, (SELECT max(a) FROM t2) AS max_a, (SELECT sum(a) FROM t2) AS sum_a, (SELECT sum(b) FROM t2) AS sum_b, (SELECT count(*) FROM sqlite_schema WHERE type='view' AND name='v1') AS view_schema_rows, (SELECT count(*) FROM sqlite_schema WHERE type='index' AND name='t2i1' AND tbl_name='t2') AS index_schema_rows, (SELECT count(*) FROM sqlite_schema WHERE type='trigger' AND name='r1' AND tbl_name='t2') AS trigger_schema_rows, (SELECT stat FROM sqlite_stat1 WHERE tbl='t2' AND idx='t2i1') AS index_stat, (SELECT * FROM pragma_integrity_check LIMIT 1) AS integrity_result;